import React, { useState, useEffect, useCallback } from 'react';
import EditorComponent from './components/EditorComponent';
import OutputConsole from './components/OutputConsole';
import RunButton from './components/RunButton';
import ThemeToggle from './components/ThemeToggle';
import EventButtons from './components/EventButtons';
import CodeSnippets from './components/CodeSnippets';
import ExecutionHistory from './components/ExecutionHistory';
import './App.css';

/**
 * Main App Component
 * Manages global state including:
 * - Code editor content
 * - Console output
 * - Theme (dark/light mode)
 * - Defined events
 */
function App() {
  // State management
  const [code, setCode] = useState(`start {
    say "Welcome to EVENTRA!"
    say "This is an event-driven programming language"
}

on click {
    say "Button clicked!"
}

on login {
    input username
    say "Hello, " + username
}`);
  
  const [output, setOutput] = useState('');
  const [events, setEvents] = useState([]);
  const [isDarkMode, setIsDarkMode] = useState(true); // Dark mode by default
  const [executionHistory, setExecutionHistory] = useState([]);
  
  // Load saved code and theme from localStorage on mount
  useEffect(() => {
    const savedCode = localStorage.getItem('eventra_code');
    const savedTheme = localStorage.getItem('eventra_theme');
    const savedHistory = localStorage.getItem('eventra_history');
    
    if (savedCode) setCode(savedCode);
    if (savedTheme) setIsDarkMode(savedTheme === 'dark');
    if (savedHistory) setExecutionHistory(JSON.parse(savedHistory));
  }, []);
  
  // Save code to localStorage whenever it changes
  const saveCode = useCallback(() => {
    localStorage.setItem('eventra_code', code);
    alert('✅ Code saved successfully!');
  }, [code]);
  
  // Load code from localStorage
  const loadCode = useCallback(() => {
    const savedCode = localStorage.getItem('eventra_code');
    if (savedCode) {
      setCode(savedCode);
      alert('✅ Code loaded successfully!');
    } else {
      alert('⚠️ No saved code found');
    }
  }, []);
  
  // Clear saved code
  const clearSavedCode = useCallback(() => {
    localStorage.removeItem('eventra_code');
    alert('🗑️ Saved code cleared!');
  }, []);
  
  // Export code to file
  const exportCode = useCallback(() => {
    const blob = new Blob([code], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'program.eventra';
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
    alert('✅ Code exported successfully!');
  }, [code]);
  
  // Import code from file
  const importCode = useCallback((event) => {
    const file = event.target.files[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (e) => {
        setCode(e.target.result);
        alert('✅ Code imported successfully!');
      };
      reader.readAsText(file);
    }
  }, []);
  
  /**
   * Toggle between dark and light theme
   */
  const toggleTheme = useCallback(() => {
    const newMode = !isDarkMode;
    setIsDarkMode(newMode);
    localStorage.setItem('eventra_theme', newMode ? 'dark' : 'light');
  }, [isDarkMode]);
  
  /**
   * Update code content
   */
  const handleCodeChange = (newCode) => {
    setCode(newCode);
  };
  
  /**
   * Load snippet code into editor
   */
  const handleSnippetSelect = (snippetCode) => {
    setCode(snippetCode);
  };
  
  /**
   * Append output to console
   */
  const appendOutput = (text) => {
    setOutput(prev => prev + text);
  };
  
  /**
   * Clear the output console
   */
  const clearOutput = () => {
    setOutput('');
  };
  
  /**
   * Set available events
   */
  const setAvailableEvents = (eventList) => {
    setEvents(eventList);
  };
  
  /**
   * Add entry to execution history
   */
  const addToHistory = useCallback((codeSnippet, success) => {
    const newEntry = {
      code: codeSnippet.substring(0, 50) + (codeSnippet.length > 50 ? '...' : ''),
      fullCode: codeSnippet,
      success,
      timestamp: new Date().toLocaleTimeString()
    };
    
    setExecutionHistory(prev => {
      const updated = [newEntry, ...prev].slice(0, 10); // Keep last 10
      localStorage.setItem('eventra_history', JSON.stringify(updated));
      return updated;
    });
  }, []);
  
  // Keyboard shortcuts
  useEffect(() => {
    const handleKeyDown = (e) => {
      // Ctrl+S - Save code
      if (e.ctrlKey && e.key === 's') {
        e.preventDefault();
        saveCode();
      }
      // Ctrl+Enter - Run code
      if (e.ctrlKey && e.key === 'Enter') {
        e.preventDefault();
        document.querySelector('.run-button')?.click();
      }
      // Ctrl+L - Load code
      if (e.ctrlKey && e.key === 'l') {
        e.preventDefault();
        loadCode();
      }
    };
    
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [saveCode, loadCode]);
  
  return (
    <div className={`app ${isDarkMode ? 'dark-mode' : 'light-mode'}`}>
      {/* Header */}
      <header className="app-header">
        <h1>EVENTRA</h1>
        <p className="subtitle">Event-Driven Programming Language</p>
        <ThemeToggle isDarkMode={isDarkMode} onToggle={toggleTheme} />
      </header>
      
      {/* Main Content */}
      <div className="main-content">
        {/* Left Panel - Editor */}
        <div className="editor-section">
          <div className="section-header">
            <h2>Code Editor</h2>
            <CodeSnippets 
              onCodeSelect={handleSnippetSelect}
              isDarkMode={isDarkMode}
            />
          </div>
          <EditorComponent 
            code={code} 
            onCodeChange={handleCodeChange}
            isDarkMode={isDarkMode}
          />
          <RunButton 
            code={code} 
            onOutput={appendOutput}
            onClear={clearOutput}
            onEventsDetected={setAvailableEvents}
            onSave={saveCode}
            onLoad={loadCode}
            addToHistory={addToHistory}
            onExport={exportCode}
            onImport={importCode}
            isDarkMode={isDarkMode}
          />
        </div>
        
        {/* Right Panel - Output & Events */}
        <div className="output-section">
          <div className="section-header">
            <h2>Output Console</h2>
          </div>
          <OutputConsole output={output} isDarkMode={isDarkMode} />
          
          <div className="section-header">
            <h2>Event Triggers</h2>
          </div>
          <EventButtons 
            events={events} 
            code={code}
            onOutput={appendOutput}
            isDarkMode={isDarkMode}
          />
          
          <ExecutionHistory 
            history={executionHistory}
            onSelectCode={setCode}
            isDarkMode={isDarkMode}
          />
        </div>
      </div>
      
      {/* Footer */}
      <footer className="app-footer">
        <p>Built with React & Spring Boot | EVENTRA © 2026</p>
      </footer>
    </div>
  );
}

export default App;
